"""Phase 13 Lesson 11: model input through stateless MCP MRTR.

Lesson: ../docs/en.md
Specification: https://modelcontextprotocol.io/specification/2026-07-28/basic/patterns/mrtr
This example uses only Python's standard library.
Run: python3 main.py
"""

from __future__ import annotations

import base64
import hashlib
import hmac
import json
import time
from copy import deepcopy
from dataclasses import dataclass
from typing import Any


PROTOCOL_VERSION = "2026-07-28"
PROTOCOL_META = "io.modelcontextprotocol/protocolVersion"
CAPABILITIES_META = "io.modelcontextprotocol/clientCapabilities"
CLIENT_INFO_META = "io.modelcontextprotocol/clientInfo"
SERVER_INFO_META = "io.modelcontextprotocol/serverInfo"
SERVER_SECRET = b"lesson-11-demo-secret-change-in-production"

FAKE_REPO = {
    "README.md": "A small notes server used to teach stateless MCP.",
    "server.py": "def dispatch(request): return handle(request)",
    "client.py": "def retry(request, inputs, state): ...",
    "LICENSE": "MIT",
    "tests/test_server.py": "def test_stateless_retry(): ...",
    "docs/intro.md": "The server has no protocol session state.",
}
TOOLS = [
    {
        "name": "summarize_repo",
        "description": "Select representative repository files and summarize them.",
        "inputSchema": {
            "type": "object",
            "properties": {
                "audience": {
                    "type": "string",
                    "description": "Audience for the final repository summary.",
                }
            },
            "required": [],
        },
    }
]


@dataclass
class McpError(Exception):
    code: int
    message: str
    data: dict[str, Any] | None = None


def request_meta(*, sampling: bool = True) -> dict[str, Any]:
    capabilities: dict[str, Any] = {"sampling": {}} if sampling else {}
    return {
        PROTOCOL_META: PROTOCOL_VERSION,
        CAPABILITIES_META: capabilities,
        CLIENT_INFO_META: {"name": "lesson-client", "version": "1.0.0"},
    }


def _server_meta() -> dict[str, Any]:
    return {SERVER_INFO_META: {"name": "mrtr-demo", "version": "1.0.0"}}


def complete(**fields: Any) -> dict[str, Any]:
    return {"resultType": "complete", **fields, "_meta": _server_meta()}


def validate_request_meta(params: dict[str, Any]) -> dict[str, Any]:
    meta = params.get("_meta")
    if not isinstance(meta, dict):
        raise McpError(-32602, "missing request _meta")
    requested_version = meta.get(PROTOCOL_META)
    if not isinstance(requested_version, str):
        raise McpError(-32602, "missing protocol version")
    if requested_version != PROTOCOL_VERSION:
        raise McpError(
            -32022,
            "unsupported protocol version",
            {"supported": [PROTOCOL_VERSION], "requested": requested_version},
        )
    capabilities = meta.get(CAPABILITIES_META)
    if not isinstance(capabilities, dict):
        raise McpError(-32602, "missing client capabilities")
    return meta


def server_discover(params: dict[str, Any]) -> dict[str, Any]:
    validate_request_meta(params)
    return complete(
        supportedVersions=[PROTOCOL_VERSION],
        capabilities={"tools": {}},
        ttlMs=300_000,
        cacheScope="public",
    )


def tools_list(params: dict[str, Any]) -> dict[str, Any]:
    validate_request_meta(params)
    return complete(
        tools=sorted(deepcopy(TOOLS), key=lambda tool: tool["name"]),
        ttlMs=60_000,
        cacheScope="public",
    )


def _b64(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).decode("ascii").rstrip("=")


def _unb64(value: str) -> bytes:
    return base64.urlsafe_b64decode(value + "=" * (-len(value) % 4))


def _arguments_digest(arguments: dict[str, Any]) -> str:
    encoded = json.dumps(arguments, sort_keys=True, separators=(",", ":")).encode()
    return hashlib.sha256(encoded).hexdigest()


def seal_request_state(payload: dict[str, Any]) -> str:
    body = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode()
    signature = hmac.new(SERVER_SECRET, body, hashlib.sha256).digest()
    return f"{_b64(body)}.{_b64(signature)}"


def verify_request_state(
    token: str,
    *,
    principal: str,
    arguments: dict[str, Any],
    now: int | None = None,
) -> dict[str, Any]:
    try:
        body_part, signature_part = token.split(".", 1)
        body = _unb64(body_part)
        supplied = _unb64(signature_part)
    except (ValueError, TypeError) as exc:
        raise McpError(-32602, "invalid requestState encoding") from exc
    expected = hmac.new(SERVER_SECRET, body, hashlib.sha256).digest()
    if not hmac.compare_digest(supplied, expected):
        raise McpError(-32602, "requestState integrity check failed")
    try:
        state = json.loads(body)
    except json.JSONDecodeError as exc:
        raise McpError(-32602, "invalid requestState payload") from exc
    if state.get("principal") != principal:
        raise McpError(-32602, "requestState principal mismatch")
    if state.get("method") != "tools/call":
        raise McpError(-32602, "requestState method mismatch")
    if state.get("argumentsDigest") != _arguments_digest(arguments):
        raise McpError(-32602, "requestState arguments mismatch")
    if int(state.get("expiresAt", 0)) < (int(time.time()) if now is None else now):
        raise McpError(-32602, "requestState expired")
    return state


def _sampling_request(prompt: str, *, intelligence: float) -> dict[str, Any]:
    return {
        "method": "sampling/createMessage",
        "params": {
            "messages": [
                {"role": "user", "content": {"type": "text", "text": prompt}}
            ],
            "systemPrompt": "Return only the requested value.",
            "modelPreferences": {
                "costPriority": round(1.0 - intelligence, 2),
                "intelligencePriority": intelligence,
            },
            "maxTokens": 400,
        },
    }


def _input_required(
    key: str,
    prompt: str,
    state: dict[str, Any],
    *,
    intelligence: float,
) -> dict[str, Any]:
    return {
        "resultType": "input_required",
        "inputRequests": {key: _sampling_request(prompt, intelligence=intelligence)},
        "requestState": seal_request_state(state),
        "_meta": _server_meta(),
    }


def _sampling_text(input_responses: Any, key: str) -> str:
    if not isinstance(input_responses, dict):
        raise McpError(-32602, "inputResponses must be an object")
    response = input_responses.get(key)
    if not isinstance(response, dict):
        raise McpError(-32602, f"missing input response: {key}")
    content = response.get("content")
    if not isinstance(content, dict) or content.get("type") != "text":
        raise McpError(-32602, f"invalid sampling response: {key}")
    text = content.get("text")
    if not isinstance(text, str) or not text.strip():
        raise McpError(-32602, f"empty sampling response: {key}")
    return text


def tools_call(params: dict[str, Any], *, principal: str) -> dict[str, Any]:
    meta = validate_request_meta(params)
    if params.get("name") != "summarize_repo":
        raise McpError(-32602, "unknown tool")
    arguments = params.get("arguments", {})
    if not isinstance(arguments, dict):
        raise McpError(-32602, "arguments must be an object")
    capabilities = meta[CAPABILITIES_META]
    if "sampling" not in capabilities:
        raise McpError(
            -32021,
            "missing required client capability",
            {"requiredCapabilities": {"sampling": {}}},
        )

    state_token = params.get("requestState")
    if state_token is None:
        state = {
            "phase": "pick",
            "principal": principal,
            "method": "tools/call",
            "argumentsDigest": _arguments_digest(arguments),
            "expiresAt": int(time.time()) + 300,
        }
        prompt = (
            "Choose three representative files and return a JSON array. Files: "
            + json.dumps(sorted(FAKE_REPO))
        )
        return _input_required("pick_files", prompt, state, intelligence=0.2)

    if not isinstance(state_token, str):
        raise McpError(-32602, "requestState must be a string")
    state = verify_request_state(
        state_token,
        principal=principal,
        arguments=arguments,
    )
    responses = params.get("inputResponses")

    if state["phase"] == "pick":
        raw_picks = _sampling_text(responses, "pick_files")
        try:
            picks = json.loads(raw_picks)
        except json.JSONDecodeError as exc:
            raise McpError(-32602, "pick_files must return JSON") from exc
        if not isinstance(picks, list) or not all(isinstance(item, str) for item in picks):
            raise McpError(-32602, "pick_files must return a string array")
        picked = [name for name in picks if name in FAKE_REPO][:3]
        if not picked:
            raise McpError(-32602, "pick_files returned no known files")
        combined = "\n\n".join(f"{name}: {FAKE_REPO[name]}" for name in picked)
        next_state = {
            **state,
            "phase": "summarize",
            "picked": picked,
            "expiresAt": int(time.time()) + 300,
        }
        prompt = "Summarize these files in two sentences:\n\n" + combined
        return _input_required("summary", prompt, next_state, intelligence=0.8)

    if state["phase"] == "summarize":
        summary = _sampling_text(responses, "summary")
        return complete(
            content=[{"type": "text", "text": summary}],
            structuredContent={"picked": state["picked"], "summary": summary},
            isError=False,
        )

    raise McpError(-32602, "unknown requestState phase")


def dispatch(
    request: dict[str, Any],
    *,
    principal: str = "user-42",
) -> dict[str, Any] | None:
    is_notification = "id" not in request
    request_id = request.get("id")
    try:
        method = request.get("method")
        params = request.get("params", {})
        if not isinstance(params, dict):
            raise McpError(-32602, "params must be an object")
        if method == "server/discover":
            result = server_discover(params)
        elif method == "tools/list":
            result = tools_list(params)
        elif method == "tools/call":
            result = tools_call(params, principal=principal)
        else:
            raise McpError(-32601, "method not found")
        if is_notification:
            return None
        return {"jsonrpc": "2.0", "id": request_id, "result": result}
    except McpError as exc:
        if is_notification:
            return None
        error: dict[str, Any] = {"code": exc.code, "message": exc.message}
        if exc.data is not None:
            error["data"] = exc.data
        return {"jsonrpc": "2.0", "id": request_id, "error": error}


def fake_host_model(input_request: dict[str, Any]) -> dict[str, Any]:
    prompt = input_request["params"]["messages"][-1]["content"]["text"]
    if "Choose three" in prompt:
        text = json.dumps(["README.md", "server.py", "docs/intro.md"])
    else:
        text = (
            "This repository demonstrates a stateless MCP server and client retry loop. "
            "Each MRTR round carries all required state without a protocol session."
        )
    return {
        "role": "assistant",
        "content": {"type": "text", "text": text},
        "model": "host-model",
        "stopReason": "endTurn",
    }


def run_mrtr() -> tuple[dict[str, Any], list[int]]:
    base_params = {
        "name": "summarize_repo",
        "arguments": {"audience": "developer"},
        "_meta": request_meta(),
    }
    request_id = 1
    response = dispatch(
        {"jsonrpc": "2.0", "id": request_id, "method": "tools/call", "params": base_params}
    )
    seen_ids = [request_id]

    while response.get("result", {}).get("resultType") == "input_required":
        pending = response["result"]
        fulfilled = {
            key: fake_host_model(input_request)
            for key, input_request in pending["inputRequests"].items()
        }
        request_id += 1
        seen_ids.append(request_id)
        retry_params = {
            **base_params,
            "inputResponses": fulfilled,
            "requestState": pending["requestState"],
        }
        response = dispatch(
            {
                "jsonrpc": "2.0",
                "id": request_id,
                "method": "tools/call",
                "params": retry_params,
            }
        )
    return response, seen_ids


def main() -> None:
    discovery = dispatch(
        {
            "jsonrpc": "2.0",
            "id": 0,
            "method": "server/discover",
            "params": {"_meta": request_meta()},
        }
    )
    print("discover:", json.dumps(discovery["result"], indent=2))
    response, request_ids = run_mrtr()
    print("independent request ids:", request_ids)
    print("final:", json.dumps(response["result"], indent=2))


if __name__ == "__main__":
    main()

// Lesson: MCP Model Input: Sampling Migration and Stateless MRTR (phase 13 / lesson 11)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/13-tools-and-protocols/11-mcp-sampling/docs/en.md
// Run: npx tsx phases/13-tools-and-protocols/11-mcp-sampling/code/main.ts

import { createHash, createHmac, timingSafeEqual } from "node:crypto";

type Json = any;
type Obj = Record<string, Json>;

const PROTOCOL_VERSION = "2026-07-28";
const PROTOCOL_META = "io.modelcontextprotocol/protocolVersion";
const CAPABILITIES_META = "io.modelcontextprotocol/clientCapabilities";
const CLIENT_INFO_META = "io.modelcontextprotocol/clientInfo";
const SERVER_INFO_META = "io.modelcontextprotocol/serverInfo";
const SERVER_SECRET = Buffer.from("lesson-11-demo-secret-change-in-production");

const FAKE_REPO: Record<string, string> = {
  "README.md": "A small notes server used to teach stateless MCP.",
  "server.py": "def dispatch(request): return handle(request)",
  "client.py": "def retry(request, inputs, state): ...",
  LICENSE: "MIT",
  "tests/test_server.py": "def test_stateless_retry(): ...",
  "docs/intro.md": "The server has no protocol session state.",
};
const TOOLS: Obj[] = [
  {
    name: "summarize_repo",
    description: "Select representative repository files and summarize them.",
    inputSchema: {
      type: "object",
      properties: {
        audience: {
          type: "string",
          description: "Audience for the final repository summary.",
        },
      },
      required: [],
    },
  },
];

class McpError extends Error {
  code: number;
  data: Obj | null;

  constructor(code: number, message: string, data: Obj | null = null) {
    super(message);
    this.code = code;
    this.data = data;
  }
}

function isDict(value: Json): value is Obj {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function compareStrings(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

function pyDumps(value: Json, sortKeys = false, compact = false): string {
  const itemSep = compact ? "," : ", ";
  const keySep = compact ? ":" : ": ";
  const encodeString = (text: string): string =>
    JSON.stringify(text).replace(/[^\x00-\x7f]/g, (ch) => "\\u" + ch.charCodeAt(0).toString(16).padStart(4, "0"));
  if (value === null || value === undefined) {
    return "null";
  }
  if (typeof value === "string") {
    return encodeString(value);
  }
  if (typeof value === "number" || typeof value === "boolean") {
    return String(value);
  }
  if (Array.isArray(value)) {
    return "[" + value.map((item) => pyDumps(item, sortKeys, compact)).join(itemSep) + "]";
  }
  const keys = Object.keys(value);
  if (sortKeys) {
    keys.sort(compareStrings);
  }
  return "{" + keys.map((key) => encodeString(key) + keySep + pyDumps(value[key], sortKeys, compact)).join(itemSep) + "}";
}

function nowSeconds(): number {
  return Math.floor(Date.now() / 1000);
}

function requestMeta(sampling = true): Obj {
  const capabilities: Obj = sampling ? { sampling: {} } : {};
  return {
    [PROTOCOL_META]: PROTOCOL_VERSION,
    [CAPABILITIES_META]: capabilities,
    [CLIENT_INFO_META]: { name: "lesson-client", version: "1.0.0" },
  };
}

function serverMeta(): Obj {
  return { [SERVER_INFO_META]: { name: "mrtr-demo", version: "1.0.0" } };
}

function complete(fields: Obj): Obj {
  return { resultType: "complete", ...fields, _meta: serverMeta() };
}

function validateRequestMeta(params: Obj): Obj {
  const meta = params._meta;
  if (!isDict(meta)) {
    throw new McpError(-32602, "missing request _meta");
  }
  const requestedVersion = meta[PROTOCOL_META];
  if (typeof requestedVersion !== "string") {
    throw new McpError(-32602, "missing protocol version");
  }
  if (requestedVersion !== PROTOCOL_VERSION) {
    throw new McpError(-32022, "unsupported protocol version", {
      supported: [PROTOCOL_VERSION],
      requested: requestedVersion,
    });
  }
  const capabilities = meta[CAPABILITIES_META];
  if (!isDict(capabilities)) {
    throw new McpError(-32602, "missing client capabilities");
  }
  return meta;
}

function serverDiscover(params: Obj): Obj {
  validateRequestMeta(params);
  return complete({
    supportedVersions: [PROTOCOL_VERSION],
    capabilities: { tools: {} },
    ttlMs: 300_000,
    cacheScope: "public",
  });
}

function toolsList(params: Obj): Obj {
  validateRequestMeta(params);
  return complete({
    tools: structuredClone(TOOLS).sort((a, b) => compareStrings(a.name, b.name)),
    ttlMs: 60_000,
    cacheScope: "public",
  });
}

function b64(data: Buffer): string {
  return data.toString("base64url");
}

function unb64(value: string): Buffer {
  if (!/^[A-Za-z0-9_-]*$/.test(value) || value.length % 4 === 1) {
    throw new TypeError("invalid base64");
  }
  return Buffer.from(value, "base64url");
}

function argumentsDigest(args: Obj): string {
  const encoded = pyDumps(args, true, true);
  return createHash("sha256").update(encoded).digest("hex");
}

function sealRequestState(payload: Obj): string {
  const body = Buffer.from(pyDumps(payload, true, true));
  const signature = createHmac("sha256", SERVER_SECRET).update(body).digest();
  return `${b64(body)}.${b64(signature)}`;
}

function verifyRequestState(token: string, principal: string, args: Obj, now: number | null = null): Obj {
  let body: Buffer;
  let supplied: Buffer;
  try {
    const dot = token.indexOf(".");
    if (dot < 0) {
      throw new TypeError("missing separator");
    }
    body = unb64(token.slice(0, dot));
    supplied = unb64(token.slice(dot + 1));
  } catch {
    throw new McpError(-32602, "invalid requestState encoding");
  }
  const expected = createHmac("sha256", SERVER_SECRET).update(body).digest();
  if (supplied.length !== expected.length || !timingSafeEqual(supplied, expected)) {
    throw new McpError(-32602, "requestState integrity check failed");
  }
  let state: Obj;
  try {
    state = JSON.parse(body.toString("utf8"));
  } catch {
    throw new McpError(-32602, "invalid requestState payload");
  }
  if (state.principal !== principal) {
    throw new McpError(-32602, "requestState principal mismatch");
  }
  if (state.method !== "tools/call") {
    throw new McpError(-32602, "requestState method mismatch");
  }
  if (state.argumentsDigest !== argumentsDigest(args)) {
    throw new McpError(-32602, "requestState arguments mismatch");
  }
  if (Math.trunc(Number(state.expiresAt ?? 0)) < (now === null ? nowSeconds() : now)) {
    throw new McpError(-32602, "requestState expired");
  }
  return state;
}

function samplingRequest(prompt: string, intelligence: number): Obj {
  return {
    method: "sampling/createMessage",
    params: {
      messages: [{ role: "user", content: { type: "text", text: prompt } }],
      systemPrompt: "Return only the requested value.",
      modelPreferences: {
        costPriority: Math.round((1.0 - intelligence) * 100) / 100,
        intelligencePriority: intelligence,
      },
      maxTokens: 400,
    },
  };
}

function inputRequired(key: string, prompt: string, state: Obj, intelligence: number): Obj {
  return {
    resultType: "input_required",
    inputRequests: { [key]: samplingRequest(prompt, intelligence) },
    requestState: sealRequestState(state),
    _meta: serverMeta(),
  };
}

function samplingText(inputResponses: Json, key: string): string {
  if (!isDict(inputResponses)) {
    throw new McpError(-32602, "inputResponses must be an object");
  }
  const response = inputResponses[key];
  if (!isDict(response)) {
    throw new McpError(-32602, `missing input response: ${key}`);
  }
  const content = response.content;
  if (!isDict(content) || content.type !== "text") {
    throw new McpError(-32602, `invalid sampling response: ${key}`);
  }
  const text = content.text;
  if (typeof text !== "string" || !text.trim()) {
    throw new McpError(-32602, `empty sampling response: ${key}`);
  }
  return text;
}

function toolsCall(params: Obj, principal: string): Obj {
  const meta = validateRequestMeta(params);
  if (params.name !== "summarize_repo") {
    throw new McpError(-32602, "unknown tool");
  }
  const args = "arguments" in params ? params.arguments : {};
  if (!isDict(args)) {
    throw new McpError(-32602, "arguments must be an object");
  }
  const capabilities = meta[CAPABILITIES_META];
  if (!("sampling" in capabilities)) {
    throw new McpError(-32021, "missing required client capability", {
      requiredCapabilities: { sampling: {} },
    });
  }

  const stateToken = params.requestState;
  if (stateToken === undefined || stateToken === null) {
    const state = {
      phase: "pick",
      principal,
      method: "tools/call",
      argumentsDigest: argumentsDigest(args),
      expiresAt: nowSeconds() + 300,
    };
    const prompt =
      "Choose three representative files and return a JSON array. Files: " +
      pyDumps(Object.keys(FAKE_REPO).sort(compareStrings));
    return inputRequired("pick_files", prompt, state, 0.2);
  }

  if (typeof stateToken !== "string") {
    throw new McpError(-32602, "requestState must be a string");
  }
  const state = verifyRequestState(stateToken, principal, args);
  const responses = params.inputResponses;

  if (state.phase === "pick") {
    const rawPicks = samplingText(responses, "pick_files");
    let picks: Json;
    try {
      picks = JSON.parse(rawPicks);
    } catch {
      throw new McpError(-32602, "pick_files must return JSON");
    }
    if (!Array.isArray(picks) || !picks.every((item) => typeof item === "string")) {
      throw new McpError(-32602, "pick_files must return a string array");
    }
    const picked = (picks as string[]).filter((name) => name in FAKE_REPO).slice(0, 3);
    if (picked.length === 0) {
      throw new McpError(-32602, "pick_files returned no known files");
    }
    const combined = picked.map((name) => `${name}: ${FAKE_REPO[name]}`).join("\n\n");
    const nextState = {
      ...state,
      phase: "summarize",
      picked,
      expiresAt: nowSeconds() + 300,
    };
    const prompt = "Summarize these files in two sentences:\n\n" + combined;
    return inputRequired("summary", prompt, nextState, 0.8);
  }

  if (state.phase === "summarize") {
    const summary = samplingText(responses, "summary");
    return complete({
      content: [{ type: "text", text: summary }],
      structuredContent: { picked: state.picked, summary },
      isError: false,
    });
  }

  throw new McpError(-32602, "unknown requestState phase");
}

function dispatch(request: Obj, principal = "user-42"): Obj | null {
  const isNotification = !("id" in request);
  const requestId = request.id ?? null;
  try {
    const method = request.method;
    const params = "params" in request ? request.params : {};
    if (!isDict(params)) {
      throw new McpError(-32602, "params must be an object");
    }
    let result: Obj;
    if (method === "server/discover") {
      result = serverDiscover(params);
    } else if (method === "tools/list") {
      result = toolsList(params);
    } else if (method === "tools/call") {
      result = toolsCall(params, principal);
    } else {
      throw new McpError(-32601, "method not found");
    }
    if (isNotification) {
      return null;
    }
    return { jsonrpc: "2.0", id: requestId, result };
  } catch (exc) {
    if (!(exc instanceof McpError)) {
      throw exc;
    }
    if (isNotification) {
      return null;
    }
    const error: Obj = { code: exc.code, message: exc.message };
    if (exc.data !== null) {
      error.data = exc.data;
    }
    return { jsonrpc: "2.0", id: requestId, error };
  }
}

function fakeHostModel(inputRequest: Obj): Obj {
  const messages: Obj[] = inputRequest.params.messages;
  const prompt: string = messages[messages.length - 1].content.text;
  let text: string;
  if (prompt.includes("Choose three")) {
    text = pyDumps(["README.md", "server.py", "docs/intro.md"]);
  } else {
    text =
      "This repository demonstrates a stateless MCP server and client retry loop. " +
      "Each MRTR round carries all required state without a protocol session.";
  }
  return {
    role: "assistant",
    content: { type: "text", text },
    model: "host-model",
    stopReason: "endTurn",
  };
}

function runMrtr(): [Obj, number[]] {
  const baseParams: Obj = {
    name: "summarize_repo",
    arguments: { audience: "developer" },
    _meta: requestMeta(),
  };
  let requestId = 1;
  let response = dispatch({ jsonrpc: "2.0", id: requestId, method: "tools/call", params: baseParams }) as Obj;
  const seenIds = [requestId];

  while ((response.result ?? {}).resultType === "input_required") {
    const pending = response.result;
    const fulfilled: Obj = {};
    for (const [key, inputRequest] of Object.entries(pending.inputRequests as Obj)) {
      fulfilled[key] = fakeHostModel(inputRequest);
    }
    requestId += 1;
    seenIds.push(requestId);
    const retryParams = {
      ...baseParams,
      inputResponses: fulfilled,
      requestState: pending.requestState,
    };
    response = dispatch({
      jsonrpc: "2.0",
      id: requestId,
      method: "tools/call",
      params: retryParams,
    }) as Obj;
  }
  return [response, seenIds];
}

function main(): void {
  const discovery = dispatch({
    jsonrpc: "2.0",
    id: 0,
    method: "server/discover",
    params: { _meta: requestMeta() },
  }) as Obj;
  console.log("discover:", JSON.stringify(discovery.result, null, 2));
  const [response, requestIds] = runMrtr();
  console.log("independent request ids:", "[" + requestIds.join(", ") + "]");
  console.log("final:", JSON.stringify(response.result, null, 2));
}

main();

"""Tests for the stateless MCP MRTR sampling migration lesson."""

from __future__ import annotations

import importlib.util
import json
import sys
import unittest
from pathlib import Path


MODULE_PATH = Path(__file__).resolve().parents[1] / "main.py"
SPEC = importlib.util.spec_from_file_location("lesson11_main", MODULE_PATH)
assert SPEC and SPEC.loader
main = importlib.util.module_from_spec(SPEC)
sys.modules[SPEC.name] = main
SPEC.loader.exec_module(main)


def tool_request(request_id: int = 1, *, sampling: bool = True) -> dict:
    return {
        "jsonrpc": "2.0",
        "id": request_id,
        "method": "tools/call",
        "params": {
            "name": "summarize_repo",
            "arguments": {"audience": "developer"},
            "_meta": main.request_meta(sampling=sampling),
        },
    }


class SamplingMrtrTests(unittest.TestCase):
    def test_discovery_is_complete_and_cacheable(self) -> None:
        response = main.dispatch(
            {
                "jsonrpc": "2.0",
                "id": 0,
                "method": "server/discover",
                "params": {"_meta": main.request_meta()},
            }
        )
        self.assertEqual(response["result"]["resultType"], "complete")
        self.assertEqual(response["result"]["supportedVersions"], ["2026-07-28"])
        self.assertEqual(response["result"]["ttlMs"], 300_000)
        self.assertIn(main.SERVER_INFO_META, response["result"]["_meta"])

    def test_tools_list_is_deterministic_cacheable_and_described(self) -> None:
        response = main.dispatch(
            {
                "jsonrpc": "2.0",
                "id": 1,
                "method": "tools/list",
                "params": {"_meta": main.request_meta()},
            }
        )
        result = response["result"]
        self.assertEqual(result["resultType"], "complete")
        self.assertEqual(result["ttlMs"], 60_000)
        self.assertEqual(result["cacheScope"], "public")
        self.assertIn(main.SERVER_INFO_META, result["_meta"])
        self.assertEqual(
            [tool["name"] for tool in result["tools"]],
            sorted(tool["name"] for tool in result["tools"]),
        )
        descriptor = result["tools"][0]
        self.assertEqual(descriptor["name"], "summarize_repo")
        self.assertEqual(descriptor["inputSchema"]["type"], "object")

    def test_tools_list_returns_independent_descriptors(self) -> None:
        request = {
            "jsonrpc": "2.0",
            "id": 2,
            "method": "tools/list",
            "params": {"_meta": main.request_meta()},
        }
        first = main.dispatch(request)["result"]["tools"]
        first[0]["inputSchema"]["properties"]["audience"]["type"] = "integer"
        second = main.dispatch({**request, "id": 3})["result"]["tools"]
        self.assertEqual(
            second[0]["inputSchema"]["properties"]["audience"]["type"],
            "string",
        )

    def test_initial_call_returns_embedded_sampling_request(self) -> None:
        response = main.dispatch(tool_request())
        result = response["result"]
        self.assertEqual(result["resultType"], "input_required")
        self.assertEqual(
            result["inputRequests"]["pick_files"]["method"],
            "sampling/createMessage",
        )
        self.assertIsInstance(result["requestState"], str)

    def test_client_driver_uses_fresh_ids_and_finishes(self) -> None:
        response, request_ids = main.run_mrtr()
        self.assertEqual(request_ids, [1, 2, 3])
        self.assertEqual(response["result"]["resultType"], "complete")
        self.assertFalse(response["result"]["isError"])
        self.assertEqual(len(response["result"]["structuredContent"]["picked"]), 3)

    def test_unsupported_protocol_version_is_rejected(self) -> None:
        request = tool_request()
        request["params"]["_meta"][main.PROTOCOL_META] = "2025-11-25"
        response = main.dispatch(request)
        self.assertEqual(response["error"]["code"], -32022)
        self.assertEqual(
            response["error"]["data"],
            {"supported": [main.PROTOCOL_VERSION], "requested": "2025-11-25"},
        )

    def test_missing_request_metadata_is_rejected(self) -> None:
        request = tool_request()
        del request["params"]["_meta"]
        response = main.dispatch(request)
        self.assertEqual(response["error"]["code"], -32602)

    def test_non_string_protocol_version_is_invalid_params(self) -> None:
        request = tool_request()
        request["params"]["_meta"][main.PROTOCOL_META] = None
        response = main.dispatch(request)
        self.assertEqual(response["error"]["code"], -32602)

    def test_sampling_capability_is_required(self) -> None:
        response = main.dispatch(tool_request(sampling=False))
        self.assertEqual(response["error"]["code"], -32021)
        self.assertEqual(
            response["error"]["data"],
            {"requiredCapabilities": {"sampling": {}}},
        )

    def test_notification_never_receives_a_json_rpc_response(self) -> None:
        request = tool_request()
        del request["id"]
        self.assertIsNone(main.dispatch(request))

    def test_request_state_tampering_is_rejected(self) -> None:
        response = main.dispatch(tool_request())
        token = response["result"]["requestState"]
        tampered = ("A" if token[0] != "A" else "B") + token[1:]
        retry = tool_request(2)
        retry["params"].update(
            {
                "requestState": tampered,
                "inputResponses": {
                    "pick_files": main.fake_host_model(
                        response["result"]["inputRequests"]["pick_files"]
                    )
                },
            }
        )
        rejected = main.dispatch(retry)
        self.assertEqual(rejected["error"]["code"], -32602)

    def test_request_state_is_bound_to_original_arguments(self) -> None:
        response = main.dispatch(tool_request())
        retry = tool_request(2)
        retry["params"]["arguments"] = {"audience": "executive"}
        retry["params"].update(
            {
                "requestState": response["result"]["requestState"],
                "inputResponses": {
                    "pick_files": {
                        "role": "assistant",
                        "content": {
                            "type": "text",
                            "text": json.dumps(["README.md"]),
                        },
                        "model": "host-model",
                        "stopReason": "endTurn",
                    }
                },
            }
        )
        rejected = main.dispatch(retry)
        self.assertEqual(rejected["error"]["code"], -32602)

    def test_expired_request_state_is_rejected(self) -> None:
        arguments = {"audience": "developer"}
        token = main.seal_request_state(
            {
                "phase": "pick",
                "principal": "user-42",
                "method": "tools/call",
                "argumentsDigest": main._arguments_digest(arguments),
                "expiresAt": 10,
            }
        )
        with self.assertRaises(main.McpError) as context:
            main.verify_request_state(
                token,
                principal="user-42",
                arguments=arguments,
                now=11,
            )
        self.assertEqual(context.exception.code, -32602)


if __name__ == "__main__":
    unittest.main()
